-- Dump completed on 2026-11-07 13:42:53




-- 0. Union of Fact Internet sales and Fact internet sales new

select*from fact_sales;
select*from fact_sales_new;

create table Sales as select*from fact_sales
union all
select*from Fact_Sales_New;

select*from sales;
SELECT COUNT(*)
FROM Sales;


-- 1.Lookup the productname from the Product sheet to Sales sheet.

select*from dim_product;
select*from sales;

alter table sales add column ProdName varchar(150);

set sql_safe_updates=0;
update Sales join dim_product on Sales.ProductKey=dim_product.ProductKey set sales.prodname=dim_product.EnglishProductName;


-- 2.Lookup the Customerfullname from the Customer and Unit Price from Product sheet to Sales sheet.

select*from dim_customer;
select*from dim_product;
select*from sales;

alter table Sales add column CustomerFullName varchar(200);

alter table Sales add index (customerkey);
alter table dim_customer add index (customerkey);

update Sales join dim_customer on Sales.customerkey=dim_customer.customerkey set Sales.Customerfullname = concat_ws(' ', dim_customer.firstname, dim_customer.middlename,
dim_customer.lastname);

alter table Sales add index (productkey);
alter table dim_product add index (productkey);

-- UnitPrice Already in Original Table
alter table sales add column UnitPrice2 decimal(10,4);                                                                     -- Unexecuted
update Sales join dim_product on sales.ProductKey=dim_product.ProductKey set sales.UnitPrice2=dim_product.`unit price`;    -- Unexecuted


-- 3. Calcuate the following fields from the Orderdatekey field (First Create a Date Field from Orderdatekey)
-- OrderDate Already in Original Table

select*from sales;
alter table sales add column OrderDate2 date;                                       -- Unexecuted
update sales set OrderDate2 = str_to_date(cast(Orderdatekey as char), '%Y%m%d');    -- Unexecuted

/*
   A.Year
   B.Monthno
   C.Monthfullname
   D.Quarter(Q1,Q2,Q3,Q4)
   E. YearMonth ( YYYY-MMM)
   F. Weekdayno
   G.Weekdayname
   H.FinancialMOnth
   I. Financial Quarter 
*/

alter table sales add column Year int, add column MonthNo int, add column MonthFullName varchar(20), add column Quarter varchar(2), add column YearMonth varchar(15),
add column WeekdayNo int, add column WeekdayName varchar(20), add column FinancialMonth int, add column FinancialQuarter varchar(2);

update sales set year = year(OrderDate), Monthno = month(OrderDate), Monthfullname = monthname(OrderDate), Quarter = concat('Q', quarter(OrderDate)),
YearMonth = date_format(OrderDate, '%Y-%b'), Weekdayno = weekday(OrderDate) + 1, Weekdayname = dayname(OrderDate), FinancialMonth = if(month(OrderDate) >= 7,
month(OrderDate) - 6, month(OrderDate) + 6), FinancialQuarter = concat('Q', quarter(date_sub(OrderDate, interval 6 month)));


-- 4. Calculate the Sales amount uning the columns(unit price,order quantity,unit discount)

-- SalesAmount Already in Original Table
alter table sales add column SalesAmount2 decimal(10,2);                          -- Unexecuted
update sales set SalesAmount2 = (unitprice * orderquantity) - discountamount;     -- Unexecuted


-- 5. Calculate the Productioncost uning the columns(unit cost ,order quantity)
-- TotalProductCost Already in Original Table

select*from sales;
alter table sales add column ProductionCost decimal(10,4);
update sales set ProductionCost = productstandardcost * orderquantity;


-- 6.Calculate the profit.

alter table sales add column GrossProfit decimal(10,4);
update sales set GrossProfit = (salesamount - productioncost);


-- 7. Create a Pivot table for month and sales (provide the Year as filter to select a particular Year)

select monthno, monthfullname as Month, concat('$ ',format(sum(salesamount), 2)) as Total_Sales from sales where year = 2013 group by monthno, monthfullname
order by monthno;


-- 8.Create a Bar chart to show yearwise Sales

select year, concat('$ ',format(sum(salesamount), 2)) as SalesAmount from sales group by year order by year;


-- 9.Create a Line Chart to show Monthwise sales

select monthno, monthfullname as Month, concat('$ ',format(sum(salesamount), 2)) as Total_Sales from sales group by monthno, monthfullname order by monthno;


-- 10.Create a Pie chart to show Quarterwise sales

select quarter, concat('$ ',format(sum(salesamount), 2)) as Total_Sales from sales group by quarter order by quarter;


-- 11.Create a combinational chart (bar and Line) to show Salesamount and Productioncost together

Select productkey, concat('$ ',format(sum(salesamount), 2)) as Total_Sales, concat('$ ',format(sum(productioncost), 2)) as Total_Prod_Cost from sales group by
productkey order by productkey;





